query.base:
TS metrics-gcp.cloudsql_postgresql.otel-*
| WHERE gcp.resource_type == "cloudsql_database"
// PostgreSQL-only metric: no engine marker needed.
// Age of the oldest transaction not yet vacuumed, in number of transactions (not seconds),
// split by what holds it: running, prepared, replication_slot or replica.
| STATS oldest_age = MAX(MAX_OVER_TIME(`cloudsql.googleapis.com/database/postgresql/vacuum/oldest_transaction_age`)),
        latest_minute_age = MIN(MIN_OVER_TIME(`cloudsql.googleapis.com/database/postgresql/vacuum/oldest_transaction_age`))
    BY database_id, attributes.oldest_transaction_type
| RENAME attributes.oldest_transaction_type AS blocker_type

breach.segment:
WHERE oldest_age IS NOT NULL
// Use the window minimum so the alert needs the age to stay high for the whole
// window (a long-lived blocker), not a single spike.
// Alert threshold (transactions). 100 million is half of PostgreSQL's default
// autovacuum_freeze_max_age (200M): vacuum cannot freeze rows older than this
// transaction, so XID utilization will keep climbing until it is ended.
// Tune to your write rate: lower for low-throughput instances.
| WHERE latest_minute_age >= 100000000
| RENAME latest_minute_age AS sustained_age
| KEEP database_id, blocker_type, sustained_age, oldest_age
| SORT sustained_age DESC
| LIMIT 100
